import ast, sys, pathlib
from importlib.metadata import packages_distributions, version
mods=set()
for p in pathlib.Path('src').glob('*.py'):
    for n in ast.walk(ast.parse(p.read_text(encoding='utf-8'))):
        if isinstance(n, ast.Import): mods |= {a.name.split('.')[0] for a in n.names}
        elif isinstance(n, ast.ImportFrom) and n.module and n.level==0: mods.add(n.module.split('.')[0])
std=set(sys.stdlib_module_names); pd_=packages_distributions()
third=sorted(m for m in mods if m not in std and m!='src')
req={l.split('==')[0].lower():l.split('==')[1] for l in open('requirements.txt').read().split()}
for m in third:
    d=pd_.get(m,['?'])[0]; v=version(d)
    print(m, '->', d, v, 'in requirements:', req.get(d.lower())==v)
"

